gaf_(){return" \xb7 \u0627\u0633\u062a\u0642\u0628\u0627\u0644"},
gafk(){return"\u0646\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645"},
