ga3n(){return"\u06a9\u0648\u0631\u062a\u06d5\u06cc\u06d5\u06a9 \u0632\u06cc\u0627\u062f \u062f\u06d5\u06a9\u0627\u062a \u0628\u06c6 \u0644\u06cc\u0633\u062a\u06cc \u062d\u0627\u06b5\u06d5\u062a\u06d5\u06a9\u0627\u0646\u06cc \u067e\u0632\u06cc\u0634\u06a9\u06cc \u0686\u0627\u067e\u06a9\u0631\u0627\u0648: \u0646\u06d5\u062f\u0631\u0627\u0648 \u0644\u06d5\u0645 \u06a9\u06d5\u0634\u0641\u06d5\u060c \u0628\u0627\u06b5\u0627\u0646\u0633\u06cc \u0633\u06d5\u0631\u06d5\u062a\u0627\u06cc\u06cc \u0644\u06d5\u06af\u06d5\u06b5 \u062d\u0627\u06b5\u06d5\u062a\u06d5\u06a9\u0627\u0646\u06cc \u062a\u0631\u060c \u0648 \u06a9\u06c6\u06cc \u0626\u06d5\u0648\u06d5\u06cc \u067e\u0632\u06cc\u0634\u06a9 \u0642\u06d5\u0631\u0632\u0627\u0631\u06d5."},
ga2e(){return"\u06a9\u0648\u0631\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06cc \u062a\u0627\u06a9\u06d5 \u067e\u0632\u06cc\u0634\u06a9 \u0644\u06d5 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06a9\u0627\u0646\u062f\u0627"},
ga2d(){return"\u0644\u06d5 \u067e\u0633\u0648\u06b5\u06d5\u06cc \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06cc \u067e\u0632\u06cc\u0634\u06a9 \u06cc\u0627\u0646 \u067e\u0633\u0648\u06b5\u06d5\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u060c \u0686\u0627\u067e\u06a9\u0631\u062f\u0646\u06cc \u0647\u06ce\u06b5\u06ce\u06a9\u06cc \u062c\u06cc\u0627\u06a9\u0631\u0627\u0648\u06d5\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9/\u067e\u0632\u06cc\u0634\u06a9 \u0628\u06d5\u062c\u06ce\u0628\u0647\u06ce\u06b5\u06d5 \u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u06cc\u06d5\u06a9 \u067e\u0632\u06cc\u0634\u06a9\u06cc \u0686\u0627\u0644\u0627\u06a9\u06cc \u0647\u06d5\u06cc\u06d5."},
ga2W(){return"\u067e\u0633\u0648\u06b5\u06d5\u06cc \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06cc \u0633\u0627\u062f\u06d5\u06a9\u0631\u0627\u0648"},
ga2V(){return"\u067e\u0633\u0648\u06b5\u06d5\u06cc \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06cc \u067e\u0634\u06a9\u0646\u06cc\u0646\u06cc \u06a9\u06c6\u062a\u0627\u06cc\u06cc \u062a\u06d5\u0646\u0647\u0627 \u0628\u06d5 \u0646\u0627\u0648\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u0648 \u067e\u0632\u06cc\u0634\u06a9 \u0648 \u06a9\u06c6\u062f\u06cc QR \u0686\u0627\u067e \u0628\u06a9\u06d5 \u2014 \u0628\u06d5 \u0642\u06d5\u0628\u0627\u0631\u06d5\u06cc\u06d5\u06a9\u06cc \u062c\u06ce\u06af\u06cc\u0631\u060c \u0628\u06c6 \u0644\u06a9\u0627\u0646\u062f\u0646 \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06d5 \u0648\u06d5\u06a9 \u0644\u06d5\u06cc\u0628\u06b5."},
